func (c *AgentSessions) GetNetwork(ctx context.Context, id string, opts *RequestOptions) (*SandboxNetwork, error) {
	out := new(SandboxNetwork)
	if err := c.t.Do(ctx, "GET", "/v2/agent-sessions/"+url.PathEscape(id)+"/network", nil, nil, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Metrics Returns an agent session's CPU, memory, disks and pressure, as its host reads them from the agent.session's own cgroup over a fifth of a second: never a call into the agent.session, so it does not wake a paused one nor keep one from its idle pause. One that is not running has no reading.
func (c *AgentSessions) Metrics(ctx context.Context, id string, q AgentSessionMetricsQuery, opts *RequestOptions) (*SandboxMetrics, error) {
	out := new(SandboxMetrics)
	if err := c.t.Do(ctx, "GET", "/v2/agent-sessions/"+url.PathEscape(id)+"/metrics", q.values(), nil, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// SetNetwork Replaces where an agent session may connect out, for its next connection and within a second for its open ones: those the new rules refuse are cut.
func (c *AgentSessions) SetNetwork(ctx context.Context, id string, in NetworkRules, opts *RequestOptions) (*SandboxNetwork, error) {
	out := new(SandboxNetwork)
	if err := c.t.Do(ctx, "PUT", "/v2/agent-sessions/"+url.PathEscape(id)+"/network", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Fork Copies an agent session as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies.
func (c *AgentSessions) Fork(ctx context.Context, id string, in ForkRequest, opts *RequestOptions) (*Forked, error) {
	out := new(Forked)
	if err := c.t.Do(ctx, "POST", "/v2/agent-sessions/"+url.PathEscape(id)+":fork", nil, in, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Snapshot Keeps an agent session's memory and disk as they are now, a snapshot to start agent-sessions from; with `image`, its disk alone as that image's next version. The agent.session runs on. Asked again with the same Idempotency-Key, it returns the same snapshot.
func (c *AgentSessions) Snapshot(ctx context.Context, id string, in SnapshotRequest, opts *RequestOptions) (*Stored, error) {
	out := new(Stored)
	if err := c.t.Do(ctx, "POST", "/v2/agent-sessions/"+url.PathEscape(id)+":snapshot", nil, in, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Update Changes its name, labels, idle pause, maxCost, autoWake, lifetime, delete protection, environment or sizes; each field left out stays as it is. A lifetime (`deleteAfterSeconds`) sent again before its end moves the end to that many seconds from now; 0 takes it off. A lifetime is refused (409 `delete_protected`) while `deleteProtection` is true. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on. One paused or stopped is not woken for it: judged at once as a live resize is (past the vCPUs it was made with 409, over its organization's limits `quota_exceeded`), its new sizes are returned at once, and its next wake grows it to them before the call that woke it runs. A smaller size, or a machine starting or failed, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412. Sent again with the same Idempotency-Key and body while it is the latest change, it returns the current state and changes nothing; the same key with a different body returns 409 idempotency_key_reused.
func (c *AgentSessions) Update(ctx context.Context, id string, in MachineUpdate, opts *RequestOptions) (*SandboxInfo, error) {
	out := new(SandboxInfo)
	if err := c.t.Do(ctx, "POST", "/v2/agent-sessions/"+url.PathEscape(id)+":update", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Screenshot Returns what an agent session's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused agent.session is resumed first.
func (c *AgentSessions) Screenshot(ctx context.Context, id string, q AgentSessionScreenshotQuery, opts *RequestOptions) ([]byte, error) {
	var out []byte
	if err := c.t.Do(ctx, "GET", "/v2/agent-sessions/"+url.PathEscape(id)+"/screenshot", q.values(), nil, Call{Idempotent: true}, opts, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// Act Moves, clicks, drags and scrolls the mouse and types on the keyboard of an agent session's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused agent.session is resumed first.
func (c *AgentSessions) Act(ctx context.Context, id string, in ActRequest, opts *RequestOptions) (*Acted, error) {
	out := new(Acted)
	if err := c.t.Do(ctx, "POST", "/v2/agent-sessions/"+url.PathEscape(id)+":act", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// RunCode Runs a cell of Python in an agent session as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused agent.session is resumed first.
func (c *AgentSessions) RunCode(ctx context.Context, id string, in RunCode, opts *RequestOptions) (*CodeRun, error) {
	out := new(CodeRun)
	if err := c.t.Do(ctx, "POST", "/v2/agent-sessions/"+url.PathEscape(id)+":runCode", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}
